<template><div><div class='flex justify-between mb-4'><h2 class='text-xl'>Pacientes</h2><router-link v-if='canCreate' to='/patients/new' class='px-3 py-2 bg-zinc-900 text-white rounded-xl'>Novo paciente</router-link></div><LoadingState v-if='loading'/><ErrorState v-else-if='error' :message='error'/><BaseCard v-else-if='items.length===0'>Nenhum paciente</BaseCard><div v-else class='space-y-2'><BaseCard v-for='p in items' :key='p.id'>{{ p.name }} - {{ p.cpf }}</BaseCard></div></div></template>
<script setup>import { computed,onMounted,ref } from 'vue';import { patientService } from '../services/patientService';import { useAuthStore } from '../stores/authStore';import LoadingState from '../components/LoadingState.vue';import ErrorState from '../components/ErrorState.vue';import BaseCard from '../components/BaseCard.vue';
const items=ref([]),loading=ref(false),error=ref('');const role=computed(()=>useAuthStore().role);const canCreate=computed(()=>['CLINIC_ADMIN','RECEPTIONIST'].includes(role.value));
onMounted(async()=>{loading.value=true;try{const d=await patientService.list();items.value=d.items||d||[]}catch(e){error.value='Erro ao buscar pacientes'}finally{loading.value=false}})
</script>
